import math
        import random
        import time

        LANGUAGE_WRAPPER = 'Let ${k1}$, ${k2}$, and ${N}$ be fixed integers. We are looking for pairs of real numbers $(a,b)$ that satisfy two conditions:\n1. The quadratic equation $x^2 + {k1}ax + {k2}b = 0$ has only integer roots.\n2. The numbers $a$ and $b$ are related by the equation $a+b={N}$.\nHow many such pairs $(a,b)$ exist?'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        def generator(rng):
    while True:
        k1_prime = rng.choice([2, 3, 5])
        k2_prime = rng.choice([p for p in [1, 2, 3, 5, 7] if math.gcd(p, k1_prime) == 1])
        g = rng.choice([1, 2, 3, 4])

        k1 = g * k1_prime
        k2 = g * k2_prime

        # We need N to be an integer. N = K.
        # M_prime = k2_prime * (k2_prime + K * g * k1_prime**2)
        # To keep M_prime from getting too large, choose K carefully.
        K = rng.randint(1, 4)
        N = K

        M_prime_val = k2_prime * (k2_prime + K * g * k1_prime**2)

        # Constraint to keep the number of divisors manageable
        if M_prime_val == 0 or M_prime_val > 5000:
            continue

        # Now solve to get the answer, to ensure it's not trivial
        R = (-k2_prime) % k1_prime

        divs = set()
        n_abs = abs(M_prime_val)
        for i in range(1, int(math.sqrt(n_abs)) + 1):
            if n_abs % i == 0:
                divs.add(i)
                divs.add(n_abs // i)

        U = set()
        for d in divs:
            if d % k1_prime == R:
                U.add(d)
            if (-d) % k1_prime == R:
                U.add(-d)

        count_U = len(U)
        num_fixed_points = 0
        if M_prime_val > 0:
            s = int(math.sqrt(M_prime_val))
            if s * s == M_prime_val:
                if s in U:
                    num_fixed_points += 1
                if -s in U and s != 0:
                    num_fixed_points += 1

        answer = (count_U + num_fixed_points) // 2

        # We want a non-trivial number of solutions, but not too many.
        if 2 < answer < 20:
            return {'k1': k1, 'k2': k2, 'N': N}

        import math

def get_integer_divisors(n):
    n = abs(n)
    if n == 0:
        return []
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(-i)
            divs.add(n // i)
            divs.add(-(n // i))
    return list(divs)

def verifier(assign):
    k1 = assign['k1']
    k2 = assign['k2']
    N = assign['N']

    if k1 == 0:
        # This case leads to infinite or one solution depending on details,
        # but the generator avoids it.
        return False, None
    if k2 == 0:
        # Roots are 0, -k1*a. b=0 => a=N. Root -k1*N must be integer.
        # This is one pair (a,b). The logic below should handle this.
        pass

    # Let roots be r1, r2. r1+r2 = -k1*a, r1*r2 = k2*b.
    # a+b=N => -(r1+r2)/k1 + r1*r2/k2 = N
    # k1*r1*r2 - k2*(r1+r2) = N*k1*k2
    # (k1*r1 - k2)(k1*r2 - k2) = k2^2 + N*k1^2*k2 = k2*(k2 + N*k1^2)
    M = k2 * (k2 + N * k1**2)

    # Let u = k1*r1 - k2, v = k1*r2 - k2. uv = M.
    # r1,r2 are integers => u,v must be integers and u,v = -k2 (mod k1).
    # Let g = gcd(k1,k2), k1=g*k1', k2=g*k2'.
    # u = g*u', v=g*v'. u'v' = M/g^2 = M'.
    # u',v' = -k2' (mod k1').

    g = math.gcd(k1, k2)
    if g == 0: return False, None # Should not happen with k1!=0

    if M % (g * g) != 0:
        # This would mean no integer solutions for r1, r2. But our M is constructed to be divisible.
        return False, None

    M_prime = M // (g * g)
    k1_prime = k1 // g
    k2_prime = k2 // g

    if k1_prime == 0: # Should not happen
        return False, None

    R = (-k2_prime) % k1_prime

    # We need to count unordered pairs {u', v'} of integer divisors of M_prime
    # such that u'*v' = M_prime and u', v' === R (mod k1_prime).
    # Let U_prime be the set of divisors of M_prime satisfying the congruence.
    # The map d -> M_prime/d is an involution on U_prime.
    # The number of pairs is ( |U_prime| + |fixed points| ) / 2.

    divs = get_integer_divisors(M_prime)
    U_prime = {d for d in divs if d % k1_prime == R}

    count_U = len(U_prime)
    num_fixed_points = 0

    if M_prime > 0:
        s = int(math.sqrt(M_prime))
        if s * s == M_prime:
            if s in U_prime:
                num_fixed_points += 1
            if s != 0 and -s in U_prime:
                num_fixed_points += 1

    # Each unordered pair {u', v'} corresponds to a unique unordered pair of roots {r1, r2},
    # which in turn corresponds to a unique pair (a,b).
    answer = (count_U + num_fixed_points) // 2

    # Validate difficulty: answer should not be too simple.
    if answer <= 2:
        return False, None # Too simple

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

